,{
"ClauseCode":"1001876"
,"ClauseContent":"COMPUTER MILLENIUM CLAUSE (CARGO)"
,"ClauseDescription":"<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">It is hereby noted and agreed that this policy does not cover any loss, damage, expense or liability of whatever nature which might otherwise be recoverable under this policy arising out of any way connected with, whether directly or indirectly. The use or operation of any computer, computer system, computer software, program or process or any electronic system where any such loss, damage, expense or liability arises, whether directly or indirectly as a consequence of: The date change to the year 2000 or any other date change and/or 2. Any change or modification of or to any such computer, computer system, computer software, program or process or any electronic system in relation to any such date change.</span></span></p>"
,"ClauseTitle":"COMPUTER MILLENIUM CLAUSE (CARGO)"
,"ClauseType":"MARINE"
,"FlagOldData":"1"
,"KodeSection":"1"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
