,{
"ClauseCode":"1001860"
,"ClauseContent":"TERMINATION OF TRANSIT CLAUSE (TERRORISM)"
,"ClauseDescription":"<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">This clause shall be paramount and shall override anything contained in this insurance inconsistent therewith.</span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">1 Notwithstanding any provision to the contrary contained in this Policy or the Clauses referred to therein, it is agreed that in so far as this Policy covers loss of or damage to the subject-matter insured caused by any terrorist or any person acting from a political motive, such cover is conditional upon the subject-matter insured being in the ordinary course of transit and, in any event, SHALL TERMINATE:</span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">either</span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">1.1 As per the transit clauses contained within the Policy, or</span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">1.2 on delivery to the Consignee&rsquo;s or other final warehouse or place of storage at the destination named herein,</span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">1.3 on delivery to any other warehouse or place of storage, whether prior to or at the destination named herein, which the Assured elect to use either for storage other than in the ordinary course of transit or for allocation or distribution, or</span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">1.4 in respect of marine transits, on the expiry of 60 days after completion of discharge overside of the goods hereby insured from the oversea vessel at the final port of discharge,</span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">1.5 in respect of air transits, on the expiry of 30 days after unloading the subject-matter insured from the aircraft at the final place of discharge, whichever shall first occur.</span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">2 If this Policy or the Clauses referred to therein specifically provide cover for inland or other further transits following on from storage, or termination as provided for above, cover will re-attach, and continues during the ordinary course of that transit terminating again in accordance with clause 1 .</span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Times New Roman,Times,serif;\"><span style=\"font-size:9px;\">3 This clause is subject to English law and practice.</span></span></p>"
,"ClauseTitle":"TERMINATION OF TRANSIT CLAUSE (TERRORISM) JC 2001/5/6"
,"ClauseType":"MARINE"
,"FlagOldData":"1"
,"KodeSection":"1"
,"pxObjClass":"ASM-FW-GISFW-Data-Clause"
,"pyExpanded":"true"
,"OldClause":[ 
{
